    const file = resolve(base, relative);
    if (!file.startsWith(base + sep) || relative.split("/").some((p) => p.startsWith(".")) || !mime[extname(file)] || ["package.json", "pagosya-project.json"].includes(relative)) { res.writeHead(404).end(); return; }
