/* Browser-review refinements: compact cover, reliable inline icons and functional checkout */
.icon{display:block;overflow:visible;color:currentColor;flex:none}
.cart-dock .icon{filter:none}
.cover{min-height:auto;align-items:stretch}
.cover-copy{justify-content:flex-start;padding-top:clamp(42px,6vh,72px)}
.cover h1{font-size:clamp(70px,7vw,108px);line-height:.79;max-width:none;margin:18px 0 22px;letter-spacing:-.02em}
.cover h1 span{display:block;width:max-content;max-width:100%;white-space:nowrap;overflow-wrap:normal}
.cover-statement{margin-bottom:22px}
.cover-photo img{object-position:88% center}
.checkout-main{padding-top:24px}
.checkout-intro{max-width:680px;margin:0 0 18px;padding-bottom:16px;border-bottom:var(--rule)}
.checkout-intro .eyebrow{margin:0 0 8px;color:var(--store-accent)}
.checkout-intro>p:last-child{font-size:16px;line-height:1.5;margin:0;max-width:58ch}
.checkout-page>h1,.checkout-page>header h1,[data-pagosya-checkout-page] .checkout-page__title{font:600 clamp(42px,5vw,70px)/.9 var(--store-heading-font);letter-spacing:-.02em;margin:0 0 20px;text-transform:uppercase}
.checkout-page>header{margin-bottom:20px}
.checkout-page form,.checkout-page__layout{gap:clamp(24px,4vw,64px)}
.checkout-page .order-item,.checkout-page .order-line,.checkout-page .order-total{padding-block:11px}
.checkout-page .checkout-button{min-height:52px;margin-top:12px}
