@media(max-width:340px){.cover h1{font-size:54px}.cover-actions{gap:14px}.checkout-page>h1,.checkout-page>header h1,[data-pagosya-checkout-page] .checkout-page__title{font-size:39px}}



/* ÓRBITA final runtime-markup polish */
/* Catalog cards: target the copy wrapper and elements emitted by the runtime. */
.menu-item{
  grid-template-columns:minmax(0,1fr) auto;
  grid-template-areas:
    "media media"
    "copy price"
    "add add";
  align-content:start;
}
.menu-item__copy{
  grid-area:copy;
  min-width:0;
  align-self:start;
}
.menu-item__copy h3{
  margin:0 0 10px;
  font:600 clamp(34px,3.2vw,46px)/.98 var(--store-heading-font);
  letter-spacing:-.015em;
  text-transform:none;
}
.menu-item__copy h3 a:after{
  content:" ↗";
  color:var(--store-accent);
}
.menu-item__copy p{
  max-width:55ch;
  margin:0;
  color:color-mix(in srgb,var(--store-foreground) 76%,transparent);
  font-size:15px;
  line-height:1.55;
}
.menu-item__price{
  grid-area:price;
  align-self:start;
  min-width:max-content;
  white-space:nowrap;
}
.menu-item .menu-add{
  grid-area:add;
  width:100%;
  align-self:start;
}
.menu-item [data-product-media],
.menu-item .menu-item__image{
  grid-area:media;
}
.menu-item:first-child{
  grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);
  grid-template-areas:
    "media copy"
    "media price"
    "media add";
  align-content:center;
}
.menu-item[data-no-image]{
  grid-template-columns:minmax(0,1fr) auto;
  grid-template-areas:
    "copy price"
    "add add";
}
.menu-item:first-child[data-no-image]{
  grid-column:span 2;
  grid-template-columns:minmax(0,1fr) auto;
  grid-template-areas:
    "copy price"
    "add add";
}

/* Checkout heading: target the plain h1 emitted inside the runtime inner wrapper. */
[data-pagosya-checkout-page] .checkout-page__inner > div > h1,
[data-pagosya-checkout-page] .checkout-page__inner > div h1:first-child{
  margin:0 0 16px;
  border:0;
  box-shadow:none;
  font:600 clamp(42px,4.3vw,56px)/.94 var(--store-heading-font);
  letter-spacing:-.02em;
  text-transform:uppercase;
}

/* Real order-item structure shared by checkout and the cart drawer. */
.checkout-page .order-item,
.cart-drawer .order-item,
dialog .order-item,
[data-pagosya-cart] .order-item{
  display:grid;
  grid-template-columns:minmax(0,1fr);
  gap:12px;
  min-width:0;
  padding:14px 0;
}
.checkout-page .order-item > div:first-child,
.cart-drawer .order-item > div:first-child,
dialog .order-item > div:first-child,
[data-pagosya-cart] .order-item > div:first-child{
  display:grid;
  grid-template-columns:minmax(0,1fr) max-content;
  align-items:start;
  gap:10px 16px;
  min-width:0;
}
.checkout-page .order-item > div:first-child strong,
.cart-drawer .order-item > div:first-child strong,
dialog .order-item > div:first-child strong,
[data-pagosya-cart] .order-item > div:first-child strong{
  min-width:0;
  font-weight:700;
  line-height:1.4;
  overflow-wrap:anywhere;
}
.checkout-page .order-item > div:first-child > span,
.cart-drawer .order-item > div:first-child > span,
dialog .order-item > div:first-child > span,
[data-pagosya-cart] .order-item > div:first-child > span{
  min-width:max-content;
  white-space:nowrap;
  word-break:keep-all;
  overflow-wrap:normal;
  flex-shrink:0;
  font:700 14px/1.4 var(--mono);
  text-align:right;
}
.checkout-page .order-item > .quantity,
.cart-drawer .order-item > .quantity,
dialog .order-item > .quantity,
[data-pagosya-cart] .order-item > .quantity{
  display:grid;
  grid-template-columns:44px minmax(44px,auto) 44px;
  align-items:center;
  justify-self:start;
  width:max-content;
  max-width:100%;
  margin:0;
}
.checkout-page .order-item > .quantity button,
.cart-drawer .order-item > .quantity button,
dialog .order-item > .quantity button,
[data-pagosya-cart] .order-item > .quantity button{
  width:44px;
  min-width:44px;
  height:44px;
  min-height:44px;
  padding:0;
  border:1px solid var(--store-border);
  border-radius:0;
  background:transparent;
  color:var(--store-foreground);
  cursor:pointer;
}
.checkout-page .order-item > .quantity output,
.cart-drawer .order-item > .quantity output,
dialog .order-item > .quantity output,
[data-pagosya-cart] .order-item > .quantity output{
  display:grid;
  place-items:center;
  min-width:44px;
  height:44px;
  padding:0 8px;
  border-block:1px solid var(--store-border);
  font:700 13px var(--mono);
  text-align:center;
}
.checkout-page .order-item > .quantity button:hover,
.cart-drawer .order-item > .quantity button:hover,
dialog .order-item > .quantity button:hover,
[data-pagosya-cart] .order-item > .quantity button:hover{
  background:var(--store-accent);
}
.checkout-page .order-item > .quantity button:focus-visible,
.cart-drawer .order-item > .quantity button:focus-visible,
dialog .order-item > .quantity button:focus-visible,
[data-pagosya-cart] .order-item > .quantity button:focus-visible{
  position:relative;
  z-index:1;
  outline:3px solid #2876d2;
  outline-offset:2px;
}

@media(max-width:900px){
  .menu-item:first-child{
    grid-column:auto;
    grid-template-columns:minmax(0,1fr) auto;
    grid-template-areas:
      "media media"
      "copy price"
      "add add";
    align-content:start;
  }
  .menu-item:first-child[data-no-image]{
    grid-column:auto;
  }
  [data-pagosya-checkout-page] .checkout-page__inner > div > h1,
  [data-pagosya-checkout-page] .checkout-page__inner > div h1:first-child{
    font-size:clamp(34px,9.5vw,40px);
    line-height:.96;
    margin-bottom:14px;
  }
}
@media(max-width:520px){
  .menu-item,
  .menu-item:first-child,
  .menu-item[data-no-image],
  .menu-item:first-child[data-no-image]{
    grid-template-columns:minmax(0,1fr);
    grid-template-areas:
      "media"
      "copy"
      "price"
      "add";
  }
  .menu-item[data-no-image],
  .menu-item:first-child[data-no-image]{
    grid-template-areas:
      "copy"
      "price"
      "add";
  }
  .menu-item__copy h3{
    font-size:34px;
  }
  .menu-item__price{
    justify-self:start;
  }
  .checkout-page .order-item > div:first-child,
  .cart-drawer .order-item > div:first-child,
  dialog .order-item > div:first-child,
  [data-pagosya-cart] .order-item > div:first-child{
    gap:8px 10px;
  }
}

